import {buildChain,PRESETS,makeEffect} from './engine.js';
export const TEMPLATES=[['eva','终幕 / 大字宣言','黑底宋体 · 非对称排版'],['post','一条影像动态','社交帖子 · 图片居中'],['memory','Best memories 2008','旧相册 · 底部题签'],['phone','未发送的短信','绿色液晶屏 · 图片与文字'],['game','存档点 1998','古早游戏 · 像素对白'],['millennium','千禧街角','冷淡柔焦 · 宽白边'],['album','独立专辑 / SIDE A','方形封面 · 编号与曲目'],['collage','剪贴日记','照片拼贴 · 胶带与纸签']];
export const PATCHES=[['dialog','RPG 对话框'],['window','经典系统窗口'],['selection','蓝色选区贴纸'],['frame','拍立得相框'],['filmframe','电影画框']];
export function composeTemplate(key,source,make){
 const layers=[],effects=[];let W=1200,H=1200,bg='#eee9de';
 const shape=(name,x,y,w,h,color,extra={})=>{const l=make('shape',{name,x,y,w,h,color,shape:'rect',...extra});layers.push(l);return l};
 const text=(content,x,y,w,size,color='#252525',extra={})=>{const l=make('text',{name:content.slice(0,24),content,x,y,w,h:size*2,fontSize:size,font:'sans-serif',weight:700,color,stroke:0,strokeColor:'#000000',layout:'normal',animate:false,wrap:true,lineHeight:1.15,...extra});layers.push(l);return l};
 const photo=(x,y,w,h,look,extra={})=>{if(!source)return;const l=make('image',{...source,id:crypto.randomUUID(),name:'照片 · 可替换',x,y,w,h,fit:'cover',rotation:0,opacity:100,hidden:false,locked:false,timing:undefined,motion:undefined,mask:undefined,...extra});layers.push(l);const p=PRESETS.find(p=>p.name===look);if(p)effects.push(...buildChain(p).map(e=>({...e,target:l.id})));return l};
 if(key==='eva'){W=1400;H=1000;bg='#030302';text('請、',390,265,800,375,'#f7f4e7',{font:'serif',weight:900,wrap:false,textScaleX:.85,glow:6,glowColor:'#a08a39'});text('我想',1090,125,600,190,'#f7f4e7',{font:'serif',weight:900,wrap:false,textScaleX:.86,glow:5});text('留\n在\n此\n刻',1250,620,250,165,'#f7f4e7',{font:'serif',weight:900,lineHeight:1.05,textScaleX:.82,glow:5});text('世界尚未結束',540,885,1120,168,'#f7f4e7',{font:'serif',weight:900,wrap:false,textScaleX:.9,glow:5});effects.push(makeEffect('grain',{params:{amount:10,speed:0}}));}
 if(key==='post'){W=1000;H=1500;bg='#ffffff';text('4:41',90,40,110,25,'#323232');text('•••   ▰',900,40,140,23,'#555555');text('‹',65,120,60,64,'#111111');text('Post',260,120,280,43,'#111111',{align:'left'});shape('导航底线',500,185,1000,1,'#eeeeee');const avatar=photo(85,260,100,100,null,{name:'头像 · 可替换',mask:{type:'ellipse',x:50,y:50,w:100,h:100,feather:0,invert:false}});text('你的名字',380,240,460,33,'#151515',{align:'left'});text('@yourname',380,287,460,29,'#777777',{align:'left',weight:400});shape('关注按钮',835,255,220,65,'#111111');text('Follow',835,255,200,30,'#ffffff');text('把今天留在这里。\n这是一段可以编辑的文字。',500,395,920,36,'#202020',{align:'left',weight:400});photo(500,865,920,790,null,{name:'帖子照片 · 可替换'});text('6:34 AM · 26 Jun 26 · 1,124 Views',500,1310,920,27,'#777777',{align:'left',weight:400});shape('分隔线',500,1352,920,1,'#dddddd');text('36 Likes    1 Bookmark',500,1395,920,29,'#303030',{align:'left',weight:400});text('♡             ↗             ☆             ⋯',500,1460,920,36,'#626764');}
 if(key==='memory'){const im=photo(600,550,1200,1100);if(im){effects.push(...[makeEffect('tone',{params:{exposure:0,contrast:-8,saturation:-22,warmth:9}}),makeEffect('digital2008')].map(e=>({...e,target:im.id})));}shape('旧相纸底边',600,1150,1200,100,'#e9e9df');const label=text('best memories 2008',600,1151,1170,78,'#424b8e',{weight:400,wrap:false,glow:3,glowColor:'#696ea3'});effects.push({...makeEffect('digital2008',{params:{resolution:500,amount:90}}),target:label.id});}
 if(key==='phone'){W=1250;H=1120;bg='#010701';for(let k=0;k<5;k++)shape('信号强度',260+k*23,170-k*9,12,18+k*18,'#75bca1');text('pinyin',440,245,480,66,'#b5d6b2',{font:'monospace',align:'left',weight:500});shape('电池外框',1000,210,95,49,'#b5d6b2');shape('电池暗部',992,210,66,33,'#010701');shape('电池触点',1053,210,10,24,'#b5d6b2');text('14/900',935,292,250,58,'#77d4b8',{font:'monospace',weight:400});shape('发光液晶屏',635,600,800,570,'#b9d7b1');text('等我五分钟抽根烟再\n走好不好？',635,440,770,65,'#183c25',{align:'left',font:'monospace',weight:400,lineHeight:1.15});const im=photo(635,650,740,360,'掌机来信',{hidden:true,name:'屏幕照片 · 显示后可替换'});text('选项',330,970,220,66,'#b9d8b3',{font:'monospace',weight:400});text('清除',960,970,220,66,'#b9d8b3',{font:'monospace',weight:400});const a=9*Math.PI/180;for(const l of layers){const dx=l.x-625,dy=l.y-560;l.x=625+dx*Math.cos(a)-dy*Math.sin(a);l.y=560+dx*Math.sin(a)+dy*Math.cos(a);l.rotation=9;}effects.push(makeEffect('lcdphoto'));}
 if(key==='game'){W=1600;H=1000;bg='#130d29';const gamePhoto=photo(800,500,1600,1000);if(gamePhoto){effects.push(...[makeEffect('dither'),makeEffect('tritone')].map(e=>({...e,target:gamePhoto.id,...(e.type==='tritone'?{color:'#26114c',color2:'#ef38c7'}:{})})));}shape('对白外框',800,805,1460,290,'#ece6f8');shape('对白底色',800,805,1440,270,'#20183c',{opacity:92});text('旅人',240,715,260,40,'#f9c3ef');text('故事仍在继续。\n你要在这里保存回忆吗？    ▼',800,830,1300,49,'#ffffff',{align:'left'});}
 if(key==='millennium'){W=1600;H=1100;bg='#ffffff';photo(800,520,1330,840,'千禧数码');text('2002 / SUMMER',1390,1035,300,18,'#a6aaa9',{weight:400});}
 if(key==='album'){bg='#e4e0d7';photo(600,530,1080,940,'冷银暗房');text('AFTER HOURS',600,180,1000,110,'#f9efdd',{font:'serif'});shape('橙色标签',1010,880,150,150,'#ef592e');text('A',1010,880,140,90,'#201d1b');text('SIDE A / 01     留声 / 2026',600,1100,1080,33,'#252525',{align:'left'});}
 if(key==='collage'){bg='#e6dcc5';photo(430,530,650,810,'夜景胶片',{rotation:-9,shadow:20});photo(880,660,460,600,'冷银暗房',{rotation:12,shadow:15});shape('纸胶带',370,160,350,70,'#c1ad80',{opacity:68,rotation:-13});shape('纸签',480,1050,830,130,'#f9f3e5',{rotation:-3});text('碎片也能组成一首歌',480,1050,760,55,'#303b35',{font:'serif',rotation:-3});}
 return {width:W,height:H,background:bg,layers,effects};
}
export function composePatch(key,W,H,make){const a=[],s=Math.min(W,H),x=W/2,y=H*.72,w=W*.78,h=s*.24;const rect=(name,x,y,w,h,color,opacity=100)=>a.push(make('shape',{name,x,y,w,h,color,opacity,shape:'rect'}));const txt=(content,x,y,w,size,color)=>a.push(make('text',{name:content,content,x,y,w,h:size*2,fontSize:Math.max(8,size),font:'monospace',weight:500,color,stroke:0,strokeColor:'#000000',layout:'normal',animate:false}));
 if(key==='selection'){rect('蓝色透明选区',x,y,w*.7,h*.4,'#3989ed',38);for(const dx of [-w*.35,w*.35]){rect('选区光标',x+dx,y,Math.max(2,s*.004),h*.55,'#287ce0');a.push(make('shape',{name:'选区手柄',x:x+dx,y:y+(dx<0?-1:1)*h*.3,w:s*.025,h:s*.025,color:'#287ce0',shape:'circle'}));}}
 if(key==='dialog'||key==='window'){rect('窗口边框',x,y,w,h,'#eeeeee');rect('窗口内容',x,y,w-s*.015,h-s*.015,key==='dialog'?'#141d42':'#d7d7d0');if(key==='window'){rect('标题栏',x,y-h*.36,w-s*.03,h*.2,'#142c87');txt('MEMORY.EXE     _ □ ×',x,y-h*.36,w*.95,s*.025,'#ffffff');}txt('在这里写下你的对白。  ▼',x,y+h*.08,w*.9,s*.04,key==='dialog'?'#ffffff':'#202020');}
 if(key==='frame'||key==='filmframe'){const b=s*(key==='frame'?.06:.11),c=key==='frame'?'#faf8ef':'#111111';rect('上框',W/2,b/2,W,b,c);rect('下框',W/2,H-b/2,W,b,c);if(key==='frame'){rect('左框',b/2,H/2,b,H,c);rect('右框',W-b/2,H/2,b,H,c);}}
 return a;
}

